import{_ as t,c as o,o as a,ag as r}from"./chunks/framework.nnfp71k2.js";const f=JSON.parse('{"title":"Web App vs Desktop App","description":"Use Calligro in the browser or download the desktop app for Windows and Linux. The differences between the two versions.","frontmatter":{"description":"Use Calligro in the browser or download the desktop app for Windows and Linux. The differences between the two versions.","head":[["link",{"rel":"canonical","href":"https://calligro.ideasalmanac.com/tutorial/guide/installation"}],["meta",{"property":"og:url","content":"https://calligro.ideasalmanac.com/tutorial/guide/installation"}],["meta",{"property":"og:title","content":"Web App vs Desktop App | Calligro"}],["meta",{"property":"og:description","content":"Use Calligro in the browser or download the desktop app for Windows and Linux. The differences between the two versions."}],["meta",{"property":"twitter:title","content":"Web App vs Desktop App | Calligro"}],["meta",{"property":"twitter:description","content":"Use Calligro in the browser or download the desktop app for Windows and Linux. The differences between the two versions."}]]},"headers":[],"relativePath":"guide/installation.md","filePath":"guide/installation.md","lastUpdated":1790617747000}'),n={name:"guide/installation.md"};function i(s,e,p,l,d,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="web-app-vs-desktop-app" tabindex="-1">Web App vs Desktop App <a class="header-anchor" href="#web-app-vs-desktop-app" aria-label="Permalink to &quot;Web App vs Desktop App&quot;">​</a></h1><p>Calligro comes in two versions with the same core features.</p><ul><li><strong><a href="https://calligro.ideasalmanac.com/webapp.html" target="_self">Web app</a></strong>: runs in your browser (chromium-based recommended)</li><li><strong><a href="https://voycawojka.itch.io/calligro" target="_blank" rel="noreferrer">Desktop app</a></strong>: download from itch.io for Windows and Linux.</li></ul><p>Both versions run everything on your computer. Your files are not uploaded to any servers (even in the web version).</p><h2 id="differences" tabindex="-1">Differences <a class="header-anchor" href="#differences" aria-label="Permalink to &quot;Differences&quot;">​</a></h2><p>For technical reasons, when using the <a href="/tutorial/guide/template-settings#pre-fill-with-a-ttf-font">pre-fill</a> option in the web app, only a limited set of commonly used fonts is available. The desktop app allows you to choose any font installed on your system.</p>',6)])])}const u=t(n,[["render",i]]);export{f as __pageData,u as default};
